struct Edge {
    int u, v, w; 
};
struct DSU {
    vector<int> p, sz;
    DSU(int n) : p(n), sz(n, 1) {
        iota(p.begin(), p.end(), 0);
    }
    int find(int x) {
        if (p[x] == x) return x;
        return p[x] = find(p[x]);
    }
    bool unite(int a, int b) {
        a = find(a); b = find(b);
        if (a == b) return false;
        if (sz[a] < sz[b]) swap(a, b);
        p[b] = a;
        sz[a] += sz[b];
        return true;
    }
};

long long mst_sum(int n, vector<Edge> &edges) {
    sort(edges.begin(), edges.end(), [](auto &e1, auto &e2) {
        return e1.w < e2.w;
    });
    DSU dsu(n);
    long long total = 0;
    int used = 0;
    for (auto [u, v, w] : edges) {
        if (dsu.unite(u, v)) {
            total += w;
            debug(u, v, w);
            used++;
            if (used == n-1) break;
        }
    }
    return total;
}
int main() {

    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n; 
    cin >> n;

    vector<Edge> edges;

    map<pair<int, int>, pair<int, int>> wmap;

    for (int i = 1; i <= n; ++i) {
        int m; 
        cin >> m;

        vector<int> verts(m);
        vector<int> costs(m);

        for (int j = 0; j < m; ++j) cin >> verts[j];
        for (int j = 0; j < m; ++j) cin >> costs[j];

        for (int j = 0; j < m; ++j) {
            int u = verts[j];
            int v = verts[(j + 1) % m]; 
            int w = costs[j];

            pair<int, int> wind = {min(u, v), max(u, v)};

            if (wmap.count(wind)) {

                auto other_pen = wmap[wind];
                int pen_k = other_pen.first; 

                edges.push_back({i, pen_k, w});

                wmap.erase(wind);
            } else {

                wmap[wind] = {i, w};
            }
        }
    }
    for (auto const& [wind, pen_info] : wmap) {
        int pen_id = pen_info.first;
        int cost = pen_info.second;
        edges.push_back({pen_id, 0, cost});
    }
    vector<Edge> edges_nonz;
    for(Edge &i : edges) {
        if(i.u != 0 and i.v != 0) {
            edges_nonz.push_back(i);
        }
    }
    cout << min(mst_sum(n + 1, edges_nonz), mst_sum(n, edges));
}